// Bundles html/index.html + html/login.html into lib/pages.js so they ship inside the server build.
import fs from 'node:fs';
const r = f => fs.readFileSync(new URL('../html/' + f, import.meta.url), 'utf8');
fs.writeFileSync(new URL('../lib/pages.js', import.meta.url),
  '// GENERATED by scripts/build-pages.mjs from html/*.html. Edit those files, not this one.\n' +
  'export const APP_HTML = ' + JSON.stringify(r('index.html')) + ';\n' +
  'export const LOGIN_HTML = ' + JSON.stringify(r('login.html')) + ';\n');
